import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o,af as l}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const q=JSON.parse('{"title":"AI 编程能力边界探索：基于 Claude Code 的 Spec Coding 项目实战","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/ai-application/dewu-ai-implementation.md","filePath":"zh/tech/ai-application/dewu-ai-implementation.md","lastUpdated":1780925527000}'),i={name:"zh/tech/ai-application/dewu-ai-implementation.md"};function d(r,e,n,c,s,h){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="ai-编程能力边界探索-基于-claude-code-的-spec-coding-项目实战" tabindex="-1">AI 编程能力边界探索：基于 Claude Code 的 Spec Coding 项目实战 <a class="header-anchor" href="#ai-编程能力边界探索-基于-claude-code-的-spec-coding-项目实战" aria-label="Permalink to &quot;AI 编程能力边界探索：基于 Claude Code 的 Spec Coding 项目实战&quot;">​</a></h1><blockquote><p>来源：<a href="https://segmentfault.com/a/1190000047648559" target="_blank" rel="noreferrer">SegmentFault - AI编程能力边界探索：基于 Claude Code 的 Spec Coding 项目实战｜得物技术</a> 替代来源：<a href="https://blog.csdn.net/u013066109/article/details/159087229" target="_blank" rel="noreferrer">CSDN - AI编程能力边界探索</a></p></blockquote><h2 id="一、前言" tabindex="-1">一、前言 <a class="header-anchor" href="#一、前言" aria-label="Permalink to &quot;一、前言&quot;">​</a></h2><p><strong>10 天，2.5 万行代码，提效 36%</strong></p><p>基于 Claude Code 的 Spec Coding（规格驱动编码）深度实战。通过 2,754 次工具调用，完成了从 0 到 1 的前端项目搭建，并在&quot;约束+示范+视觉&quot;的三层规范体系下，摸清了 AI 编程的真实能力边界。</p><h2 id="二、spec-coding-工作流" tabindex="-1">二、Spec Coding 工作流 <a class="header-anchor" href="#二、spec-coding-工作流" aria-label="Permalink to &quot;二、Spec Coding 工作流&quot;">​</a></h2><h3 id="什么是-spec-coding" tabindex="-1">什么是 Spec Coding <a class="header-anchor" href="#什么是-spec-coding" aria-label="Permalink to &quot;什么是 Spec Coding&quot;">​</a></h3><p>Spec Coding 的核心思想是：<strong>在写代码之前，先写规格文档</strong>。通过 OpenSpec 工具，每个功能变更都经历以下阶段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Proposal → Design → Specs → Tasks</span></span></code></pre></div><h3 id="spec-工作流的实际价值" tabindex="-1">Spec 工作流的实际价值 <a class="header-anchor" href="#spec-工作流的实际价值" aria-label="Permalink to &quot;Spec 工作流的实际价值&quot;">​</a></h3><ul><li><strong>减少返工</strong>：在 proposal 阶段明确为什么以及怎么做，避免实现完才发现方向不对</li><li><strong>适合复杂功能</strong>：对于需要跨多个文件多个层次的功能，tasks 分组让 AI 聚焦在当前步骤</li><li><strong>可审计</strong>：每个 Change 的完整决策链都留有记录，方便回溯</li></ul><h2 id="三、项目概览" tabindex="-1">三、项目概览 <a class="header-anchor" href="#三、项目概览" aria-label="Permalink to &quot;三、项目概览&quot;">​</a></h2><p>一个标准企业级中后台搭建，包括：</p><ul><li>表格、表单、卡片列表、数据看板等中后台核心功能</li><li>全程使用 Claude Code 辅助开发</li></ul><h2 id="四、数据概览" tabindex="-1">四、数据概览 <a class="header-anchor" href="#四、数据概览" aria-label="Permalink to &quot;四、数据概览&quot;">​</a></h2><p>所有数字来自 Claude Code 对 109 个 .jsonl 会话文件的整体数据统计：</p><table tabindex="0"><thead><tr><th>指标</th><th>数值</th></tr></thead><tbody><tr><td>开发周期</td><td>10 天</td></tr><tr><td>净增代码</td><td>25,546 行</td></tr><tr><td>人工指令</td><td>217 条</td></tr><tr><td>工具调用</td><td>2,754 次</td></tr><tr><td>整体提效</td><td>36%</td></tr></tbody></table><h3 id="工具调用分布" tabindex="-1">工具调用分布 <a class="header-anchor" href="#工具调用分布" aria-label="Permalink to &quot;工具调用分布&quot;">​</a></h3><ul><li>738 次文件读取</li><li>550 次代码编辑</li><li>662 次终端命令执行</li><li>208 次任务进度标记</li></ul><h2 id="五、开发时间线" tabindex="-1">五、开发时间线 <a class="header-anchor" href="#五、开发时间线" aria-label="Permalink to &quot;五、开发时间线&quot;">​</a></h2><h3 id="阶段一-设计阶段" tabindex="-1">阶段一：设计阶段 <a class="header-anchor" href="#阶段一-设计阶段" aria-label="Permalink to &quot;阶段一：设计阶段&quot;">​</a></h3><p>使用 Cursor + 设计规范 Rules，从概念沟通到生成高保真 UI 稿（HTML 文件），再生成标准 PRD 需求描述。</p><h3 id="阶段二-项目搭建-2-个工作日-20-条指令" tabindex="-1">阶段二：项目搭建（2 个工作日，20 条指令） <a class="header-anchor" href="#阶段二-项目搭建-2-个工作日-20-条指令" aria-label="Permalink to &quot;阶段二：项目搭建（2 个工作日，20 条指令）&quot;">​</a></h3><p>以问答式交互为主，聚焦于项目基础设施搭建和简单需求的尝试。AI 帮助熟悉技术栈、搭建项目结构、配置开发环境。</p><h3 id="阶段三-功能开发-4-个工作日-89-条指令" tabindex="-1">阶段三：功能开发（4 个工作日，89 条指令） <a class="header-anchor" href="#阶段三-功能开发-4-个工作日-89-条指令" aria-label="Permalink to &quot;阶段三：功能开发（4 个工作日，89 条指令）&quot;">​</a></h3><p>引入 Spec Coding 工作流，约 80% 的功能代码在此阶段完成。先与 AI 共同定义清晰的功能规格，然后 AI 基于&quot;蓝图&quot;自主编码。</p><h3 id="阶段四-细节打磨与生产部署-4-个工作日-108-条指令" tabindex="-1">阶段四：细节打磨与生产部署（4 个工作日，108 条指令） <a class="header-anchor" href="#阶段四-细节打磨与生产部署-4-个工作日-108-条指令" aria-label="Permalink to &quot;阶段四：细节打磨与生产部署（4 个工作日，108 条指令）&quot;">​</a></h3><p>功能迭代、系统重构和生产环境部署排障。对已有功能进行多轮优化，最终成功将应用部署上线。</p><h2 id="六、典型案例" tabindex="-1">六、典型案例 <a class="header-anchor" href="#六、典型案例" aria-label="Permalink to &quot;六、典型案例&quot;">​</a></h2><h3 id="案例一-ai-驱动产品设计" tabindex="-1">案例一：AI 驱动产品设计 <a class="header-anchor" href="#案例一-ai-驱动产品设计" aria-label="Permalink to &quot;案例一：AI 驱动产品设计&quot;">​</a></h3><p>没有产品经理、没有 UI 设计师，一个工程师如何用 AI 独立完成从产品定义到高保真原型、再到研发文档的全流程。</p><p><strong>让 AI 扮演产品经理</strong>：在 Rules 中植入「首席产品专家」Persona 提示词，将 AI 切换为&quot;先想清楚&quot;模式。</p><p><strong>让 AI 扮演 UI 设计师</strong>：通过对话式生成逐页产出高保真 HTML 文件。</p><p><strong>让 AI 生成研发可读的 PRD</strong>：基于产品经理角色，将 HTML 设计稿作为上下文，生成精确到组件行为级别的 PRD。</p><h3 id="案例二-sdd-驱动前端功能研发" tabindex="-1">案例二：SDD 驱动前端功能研发 <a class="header-anchor" href="#案例二-sdd-驱动前端功能研发" aria-label="Permalink to &quot;案例二：SDD 驱动前端功能研发&quot;">​</a></h3><p>SDD（Spec-Driven Development）+ MCP 前后端联调提效关键场景。</p><ul><li><strong>页面功能开发</strong>：人工指令 &lt; 10 条，AI 代码占比 100%</li><li><strong>前后端联调</strong>：SDD + MCP 联调路径，6 个接口零联调返工</li><li><strong>研发效率</strong>：同日额外交付两个完整模块，单日人效提升 3 倍</li></ul><h3 id="案例三-sdd-驱动系统重构" tabindex="-1">案例三：SDD 驱动系统重构 <a class="header-anchor" href="#案例三-sdd-驱动系统重构" aria-label="Permalink to &quot;案例三：SDD 驱动系统重构&quot;">​</a></h3><p><strong>重构与新功能的根本差异</strong>：新功能开发是&quot;从无到有&quot;，AI 可以大胆生成；重构是&quot;在活体系统上动手术&quot;，风险截然不同。</p><p><strong>知识问答首页重构</strong>：</p><ul><li>34 个子任务全部完成（含 4 个验证任务）</li><li>AI 全程独立执行，人工干预 &lt; 5 条指令</li><li>7 个业务组件与公共组件完成解耦</li><li><code>useChat</code> 从 20+ 方法拆为 3 个单职责 hook</li><li><code>ChatInterface</code> 从 17 个 props 缩减至 6-8 个</li></ul><h3 id="案例四-复杂问题排障" tabindex="-1">案例四：复杂问题排障 <a class="header-anchor" href="#案例四-复杂问题排障" aria-label="Permalink to &quot;案例四：复杂问题排障&quot;">​</a></h3><p><strong>问题</strong>：测试环境构建失败，过程约 4 小时，7 个会话、15+ 次方案尝试、59 条指令。</p><p><strong>根因分析</strong>（这类问题超出 AI 能力边界）：</p><ul><li><code>.npmrc</code> 历史副作用导致 native binding 被跳过</li><li>Prisma v6 境外下载沉默卡死（无错误、无超时）</li><li>pnpm 跨平台 lockfile 不一致</li></ul><p><strong>最终解法</strong>：锁定 tailwindcss 版本、配置 PRISMA_ENGINES_MIRROR、统一使用 pnpm。</p><h2 id="七、规范体系-三层结构" tabindex="-1">七、规范体系：三层结构 <a class="header-anchor" href="#七、规范体系-三层结构" aria-label="Permalink to &quot;七、规范体系：三层结构&quot;">​</a></h2><p>每层解决不同问题：</p><table tabindex="0"><thead><tr><th>层次</th><th>位置</th><th>作用</th></tr></thead><tbody><tr><td>第一层：约束层</td><td><code>.claude/rules/</code></td><td>告诉 AI「禁止什么、必须怎样」</td></tr><tr><td>第二层：示范层</td><td><code>.claude/code-design/</code></td><td>告诉 AI「标准产出长什么样」</td></tr><tr><td>第三层：视觉层</td><td><code>.claude/ui-design/</code></td><td>告诉 AI「页面应该长什么样」</td></tr></tbody></table><h3 id="第一层-约束层-claude-rules" tabindex="-1">第一层：约束层（<code>.claude/rules/</code>） <a class="header-anchor" href="#第一层-约束层-claude-rules" aria-label="Permalink to &quot;第一层：约束层（`.claude/rules/`）&quot;">​</a></h3><p>7 个规范文件约束不同维度：</p><ul><li><code>ts.md</code> — TypeScript 规范</li><li><code>code-names.md</code> — 命名规范</li><li><code>comment.md</code> — 注释规范</li><li><code>lint.md</code> — 代码风格</li><li><code>style.md</code> — 样式规范</li><li><code>pages.md</code> — 页面目录结构</li><li><code>service.md</code> — API 接口规范</li></ul><h3 id="第二层-示范层-claude-code-design" tabindex="-1">第二层：示范层（<code>.claude/code-design/</code>） <a class="header-anchor" href="#第二层-示范层-claude-code-design" aria-label="Permalink to &quot;第二层：示范层（`.claude/code-design/`）&quot;">​</a></h3><p>预置&quot;标准模板代码&quot;，AI 生成新页面时可直接参照：</p><ul><li><code>pro-table/</code> — 通用列表页模板</li><li><code>pro-form/</code> — 通用表单页模板</li><li><code>editable-pro-table/</code> — 可编辑表格模板</li><li><code>drawer/</code> — 抽屉组件模板</li></ul><h3 id="第三层-视觉层-claude-ui-design" tabindex="-1">第三层：视觉层（<code>.claude/ui-design/</code>） <a class="header-anchor" href="#第三层-视觉层-claude-ui-design" aria-label="Permalink to &quot;第三层：视觉层（`.claude/ui-design/`）&quot;">​</a></h3><p>存放 HTML 设计稿，AI 可读取其中的结构和样式信息。</p><h3 id="规范约束的实际效果" tabindex="-1">规范约束的实际效果 <a class="header-anchor" href="#规范约束的实际效果" aria-label="Permalink to &quot;规范约束的实际效果&quot;">​</a></h3><p><strong>正面效果</strong>：</p><ul><li>所有接口函数均以 <code>fetch{Name}Api</code> 命名，205 个文件保持高度一致</li><li><code>constants/</code>、<code>services/</code>、<code>hooks/</code>、<code>components/</code> 分层在每个新页面中被正确创建</li><li>CRUD 页面均参照 <code>pro-table</code> 模板，代码结构高度一致</li></ul><p><strong>需要人工干预的案例</strong>：</p><ul><li>2/24 — AI 将所有代码写在单文件中，未按规范分层</li><li>2/27 — AI 错误使用 <code>.less</code> 后缀，项目实际使用 SCSS</li></ul><h2 id="八、mcp-工具" tabindex="-1">八、MCP 工具 <a class="header-anchor" href="#八、mcp-工具" aria-label="Permalink to &quot;八、MCP 工具&quot;">​</a></h2><h3 id="mcp-一-接口文档直连" tabindex="-1">MCP 一：接口文档直连 <a class="header-anchor" href="#mcp-一-接口文档直连" aria-label="Permalink to &quot;MCP 一：接口文档直连&quot;">​</a></h3><p>AI 可以根据接口 URL 自动拉取完整接口文档——包括入参、出参、枚举值、必填项。</p><ul><li>累计调用 21 次，完成 39 个接口联调</li><li><code>interface.ts</code> 类型定义质量高，字段注释完整</li></ul><h3 id="mcp-二-飞书云文档直读" tabindex="-1">MCP 二：飞书云文档直读 <a class="header-anchor" href="#mcp-二-飞书云文档直读" aria-label="Permalink to &quot;MCP 二：飞书云文档直读&quot;">​</a></h3><p>AI 可以直接读取飞书云文档内容，无需用户手工复制粘贴。</p><h2 id="九、ai-能力边界框架" tabindex="-1">九、AI 能力边界框架 <a class="header-anchor" href="#九、ai-能力边界框架" aria-label="Permalink to &quot;九、AI 能力边界框架&quot;">​</a></h2><h3 id="ai-是一个-顶级执行者" tabindex="-1">AI 是一个&quot;顶级执行者&quot; <a class="header-anchor" href="#ai-是一个-顶级执行者" aria-label="Permalink to &quot;AI 是一个&quot;顶级执行者&quot;&quot;">​</a></h3><blockquote><p>AI 是一个极度服从、无限耐心、但没有内部业务知识常识的&quot;顶级执行者&quot;。</p></blockquote><ul><li><strong>极度服从</strong>：AI 会一字不差地执行你写的规范，不会主动质疑</li><li><strong>无限耐心</strong>：34 个任务的重构、跨会话的上下文恢复，AI 做起来没有摩擦成本</li><li><strong>没有内部业务常识</strong>：AI 不知道你们公司的部署环境，不知道接口版本变化</li></ul><h3 id="按需求颗粒度选择协作模式" tabindex="-1">按需求颗粒度选择协作模式 <a class="header-anchor" href="#按需求颗粒度选择协作模式" aria-label="Permalink to &quot;按需求颗粒度选择协作模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>需求颗粒度</th><th>协作模式</th><th>场景</th></tr></thead><tbody><tr><td>小颗粒</td><td>对话式</td><td>改文案、修显隐逻辑、调 CSS</td></tr><tr><td>中颗粒标准化</td><td>Rules/Skills</td><td>标准 CRUD、简单业务组件</td></tr><tr><td>中大颗粒复杂</td><td>OpenSpec SDD</td><td>重构核心逻辑、复杂业务模块</td></tr></tbody></table><h3 id="ai-失效的三种模式" tabindex="-1">AI 失效的三种模式 <a class="header-anchor" href="#ai-失效的三种模式" aria-label="Permalink to &quot;AI 失效的三种模式&quot;">​</a></h3><p><strong>模式一：规范真空</strong></p><ul><li>任务涉及的领域没有规范约束</li><li>应对：在 CLAUDE.md 或 code-design 中补充规范</li></ul><p><strong>模式二：信息孤岛</strong></p><ul><li>AI 掌握的信息是当前会话快照，看不到系统外状态</li><li>应对：跨平台、跨环境的依赖在架构设计阶段提前锁定</li></ul><p><strong>模式三：任务目标模糊</strong></p><ul><li>AI 把&quot;该问人的问题&quot;当成&quot;执行问题&quot;来解决</li><li>应对：Spec 工作流的 proposal 阶段强制要求先描述&quot;Why&quot;</li></ul><h2 id="十、开发者角色的重构" tabindex="-1">十、开发者角色的重构 <a class="header-anchor" href="#十、开发者角色的重构" aria-label="Permalink to &quot;十、开发者角色的重构&quot;">​</a></h2><p>AI Coding 不是让开发者&quot;消失&quot;，而是让开发者的工作向上迁移：</p><ul><li><strong>规范设计能力</strong>成为核心竞争力</li><li><strong>系统性思维</strong>变得更重要</li><li><strong>质量意识前移</strong>：在方案设计/任务执行阶段就介入</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><blockquote><p>AI Coding 的本质不仅仅是&quot;用 AI 写代码&quot;，而是用结构化的规范和工作流把不确定性消除在执行之前——AI 负责在确定性空间里高速执行，人负责维护和扩展那个确定性空间的边界。</p><p><strong>规范是杠杆，AI 是力，Spec 工作流是支点。</strong></p></blockquote>',86)])])}const m=a(i,[["render",d]]);export{q as __pageData,m as default};
